import {uploadBrowserFile} from './personal-upload.js';
import {downloadBrowserPath,filePath} from './file-transfer-ui.js';
import {createTrashUI} from './trash-ui.js';
import {cloudImportHTML,cloudImportUI} from './cloud-import-ui.js';
import {transferBytes} from './data-route.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function datasetRows(rows){return rows.map(row=>`<tr><td>${esc(row.name||row.dataset)}</td><td>${transferBytes(row.size)}</td><td>${esc(row.ownerName||row.uploadedBy||'未知')}</td><td>${esc(row.modifiedAt?new Date(typeof row.modifiedAt==='number'?row.modifiedAt*1000:row.modifiedAt).toLocaleString('zh-CN'):'未知')}</td><td><button type="button" class="button" data-dataset-open="${esc(row.dataset)}">浏览</button><button type="button" class="button" data-dataset-download="${esc(row.dataset)}">下载</button><button type="button" class="button danger" data-dataset-delete="${esc(row.dataset)}">删除</button></td></tr>`).join('');}
export function datasetsUI(store,toast){
  const section=document.querySelector('#page-datasets');let identity='',machineIds='',turn=0,busy=false,selected='',path='.',cursor=null,cloud,trash;
  const q=s=>section.querySelector(s),machine=()=>q('[name=dataset-machine]')?.value,scope=()=>({machine:machine(),area:'dataset',dataset:selected});
  const status=text=>{q('[data-dataset-status]').textContent=text;};
  const controls=()=>{for(const button of section.querySelectorAll('[data-dataset-open],[data-dataset-download],[data-dataset-delete],#dataset-refresh,#dataset-upload-form button,[data-file-path],#dataset-file-up,#dataset-file-more'))button.disabled=busy||!store.principal||!machine();cloud?.controls();trash?.update();};
  async function run(action){if(busy)return;const token=turn;busy=true;controls();try{await action(()=>token===turn);}catch(error){if(token===turn){status(error.message);toast(error.message);}}finally{if(token===turn){busy=false;controls();}}}
  async function load(){const token=turn,result=await store.call('datasets.list',{machine:machine()});if(token!==turn)return;q('[data-dataset-list]').innerHTML=datasetRows(result.datasets||[]);status(result.datasets?.length?'':'还没有数据集，上传文件即可新建。');}
  async function browse(target='.',next=false){const token=turn;path=target;q('[data-dataset-current]').textContent=selected+' / '+path;q('[data-dataset-files]').hidden=false;const page=await store.call('files.list',{...scope(),path,limit:1000,...(next&&cursor?{cursor}:{})});if(token!==turn)return;cursor=page.hasMore?page.nextCursor:null;const html=(page.entries||[]).filter(row=>['file','directory'].includes(row.type)).map(row=>`<button type="button" class="button quiet" data-file-path="${esc(filePath(path,row.name))}" data-file-type="${row.type}">${row.type==='directory'?'▱':'□'} ${esc(row.name)} ${row.type==='file'?transferBytes(row.size):''}</button>`).join('');if(next)q('[data-dataset-file-list]').insertAdjacentHTML('beforeend',html);else q('[data-dataset-file-list]').innerHTML=html||'<p>空目录。</p>';q('#dataset-file-more').hidden=!cursor;q('[name=upload-dataset]').value=selected;}
  function build(){
    cloud?.reset();section.innerHTML=`<header><h2>数据集</h2><p>数据集是共享目录，容器内路径为 /datasets；删除可能影响正在运行的任务。</p></header><nav class="data-room-tabs"><a href="#datasets" aria-current="page">数据集</a><a href="#datasets/transfers">传输与导入</a></nav><label>服务器<select name="dataset-machine"></select></label><button type="button" class="button" id="dataset-refresh">刷新</button><div class="live-table-wrap"><table class="live-table"><thead><tr><th>名字</th><th>大小</th><th>上传人</th><th>修改时间</th><th>操作</th></tr></thead><tbody data-dataset-list></tbody></table></div><section data-dataset-files hidden><h3 data-dataset-current></h3><button type="button" class="button quiet" id="dataset-file-up">上一级</button><div class="file-actions" data-dataset-file-list></div><button type="button" class="button" id="dataset-file-more" hidden>下一页</button></section><details class="data-workspace-card"><summary>上传到新建或已有数据集</summary><form id="dataset-upload-form"><label>数据集目录名<input name="upload-dataset" required></label><label>目标相对目录<input name="upload-directory" value="."></label><label>选择文件<input name="upload-files" type="file" multiple></label><label>或选择目录<input name="upload-folder" type="file" webkitdirectory multiple></label><label>续传编号（新上传留空）<input name="upload-key"></label><button type="submit" class="button primary">上传 / 续传</button></form></details><p data-dataset-status role="status"></p>${cloudImportHTML(store.principal?.role==='admin',store.users||store.data?.users||[])}`;
    trash=createTrashUI({call:(...args)=>store.call(...args),getContext:()=>({owner:store.principal?.userId,machine:machine(),enabled:!!store.principal&&!!machine(),isAdmin:store.principal?.role==='admin'}),changed:load,toast});section.append(trash.element);cloud ||= cloudImportUI(store,section,toast);
    q('[name=dataset-machine]').addEventListener('change',()=>{turn++;busy=false;selected='';q('[data-dataset-files]').hidden=true;controls();void run(load);});
    q('#dataset-refresh').addEventListener('click',()=>void run(load));
    section.onclick=event=>{const b=event.target.closest('button');if(!b||b.disabled)return;
      if(b.dataset.datasetOpen){selected=b.dataset.datasetOpen;return void run(()=>browse());}
      if(b.dataset.datasetDownload)return void run(()=>downloadBrowserPath((...args)=>store.call(...args),{machine:machine(),area:'dataset',dataset:b.dataset.datasetDownload},'.',{directory:true,onProgress:row=>status(row.path+' · '+row.offset+' / '+row.size)}));
      if(b.dataset.datasetDelete)return void run(async current=>{const dataset=b.dataset.datasetDelete,cache='dataset-delete:'+store.principal.userId+':'+machine()+':'+dataset,key=sessionStorage.getItem(cache)||crypto.randomUUID();sessionStorage.setItem(cache,key);status('删除编号：'+key);const result=await store.call('datasets.delete',{machine:machine(),dataset,key});if(!current())return;if(result.state==='TRASHED'){sessionStorage.removeItem(cache);await load();status('已删除，7 天内可在回收站恢复。');}else status('结果未知，请按原编号查询：'+key);});
      if(b.dataset.filePath)return void run(()=>b.dataset.fileType==='directory'?browse(b.dataset.filePath):downloadBrowserPath((...args)=>store.call(...args),scope(),b.dataset.filePath,{onProgress:row=>status(row.path+' · '+row.offset+' / '+row.size)}));
      if(b.id==='dataset-file-up')return void run(()=>browse(path.includes('/')?path.slice(0,path.lastIndexOf('/')):'.'));
      if(b.id==='dataset-file-more')return void run(()=>browse(path,true));
    };
    q('#dataset-upload-form').addEventListener('submit',event=>{event.preventDefault();void run(async current=>{
      const files=[...q('[name=upload-files]').files,...q('[name=upload-folder]').files].sort((a,b)=>(a.webkitRelativePath||a.name).localeCompare(b.webkitRelativePath||b.name)),dataset=q('[name=upload-dataset]').value.trim(),folder=q('[name=upload-directory]').value.trim()||'.';if(!files.length)throw Error('请选择文件或目录。');
      const key=q('[name=upload-key]').value.trim()||crypto.randomUUID();q('[name=upload-key]').value=key;
      const cache='dataset-upload:'+store.principal.userId+':'+key,keys=JSON.parse(localStorage.getItem(cache)||'{}');
      for(const file of files){const relative=file.webkitRelativePath||file.name,target=folder==='.'?relative:folder+'/'+relative;keys[target]||=files.length===1?key:crypto.randomUUID();localStorage.setItem(cache,JSON.stringify(keys));await uploadBrowserFile(file,{call:(...args)=>store.call(...args),machine:machine(),area:'dataset',dataset,path:target,key:keys[target],overwrite:true,onProgress:row=>{if(current())status(target+' · '+row.offset+' / '+file.size+' · '+key);}});if(!current())return;}
      await load();status('上传完成 · '+key);q('[name=upload-key]').value='';
    });});
  }
  return ()=>{
    const next=JSON.stringify([store.authGeneration,store.principal?.userId]);if(next!==identity||!q('[name=dataset-machine]')){identity=next;turn++;busy=false;machineIds='';build();}
    const machines=store.principal?store.data?.machines||[]:[],ids=machines.map(row=>row.id).join(',');if(ids!==machineIds){machineIds=ids;const previous=machine();q('[name=dataset-machine]').innerHTML=machines.map(row=>`<option value="${esc(row.id)}">${esc(row.id)}</option>`).join('');if(machines.some(row=>row.id===previous))q('[name=dataset-machine]').value=previous;if(machine())void run(load);}
    controls();
  };
}
